    "initials": "SG",
    "description": "\"Slow German - lerne Deutsch mit Annik!\" ist ein Podcast von Annik Rubens. Er existiert seit 2007. Ziel ist es, Deutschlernenden auf der ganzen Welt Übungen für das Hörverständnis zur Verfügung zu stellen. Mit \"Slow German\" kannst Du Deinen Wortschatz erweitern. Lerne neue deutsche Vokabeln und trainiere Dein Verständnis der gesprochenen Sprache ab Level B1. Außerdem lernst Du spielerisch etwas über die Landeskunde - kurze und leicht verständliche Texte über die deutsche Kultur und das deutsche Leben. Lernmaterial und Premium Content gibt es unter www.slowgerman.com. Abonniere diesen Podcast, um keine neuen Folgen zu verpassen! Episoden gibt es alle 2 Wochen, immer mit viel Liebe gemacht.",
