    "initials": "DM",
    "description": "Hallo! I’m Lari ☀️ A trained teacher specialized in teaching German as a foreign language (DaF) and German as a second language (DaZ). I spend my weekdays teaching young learners in the classroom and create German learning content in my free time as a personal creative outlet. This allows me to support not only my in-person students in achieving their goals, but also to reach even more people who want to learn German for free. About this channel: Learn German the easy way with educational content designed for German learners using comprehensible input. Stories and first-person statements (\"I\") are for learning purposes only and aren’t necessarily based on my personal life or views. Only my dearest subscribers know that I’m a coffee addict. ☕️ If you'd like to support my work, consider buying me a coffee for a little energy boost — so I can keep making more German learning videos for you! 🤩💪💛",
