    "initials": "FA",
    "description": "Apprenez à parler français de façon automatique et sans effort avec Français Authentique Mission : Aider les gens qui veulent améliorer leur niveau de français Mettre à disposition des articles en français intéressants et authentiques Description de l'entreprise Vous avez vécu en France ? Vous avez appris le français à l'école ? Vous avez pris des cours de français ? Vous aimez la langue et la culture française ? ...Afficher la suite Description : Français Authentique s'adresse aux gens dont le français n'est pas la langue maternelle mais qui possèdent de solides bases dans cette langue. Vous avez vécu en France, travaillé dans un pays francophone ou simplement étudié le français à l'école ? Ce site est fait pour vous. Vous aurez l'occasion ici de lire et écouter du français 100% authentique. Tous les articles sont créés par des gens dont le français est la langue maternelle.",
