    "avatar": "https://i.scdn.co/image/ab6765630000ba8abd69ca14a6d766dc2f47adc1",
    "initials": "JE",
    "description": "Un vrai journal d’information pour suivre l’actualité internationale en français. Du lundi au vendredi sur l'antenne de RFI à 16 h (TU) puis sur le site Le français facile avec RFI avec sa transcription. Chaque semaine, l'équipe du service Langue française de RFI vous propose en bonus deux exercices pour vous aider à comprendre un sujet d'actualité en français et enrichir votre vocabulaire.",
