    "id": "it_geopop",
    "category": "youtube",
    "title": "Geopop",
    "url": "https://www.youtube.com/@geopop",
    "avatar": "https://yt3.googleusercontent.com/oE0UEzTJ3tQwypwVB-CLljtel5wErzFm07vlAg4BqUlOdK3sHA7Pt4tRyIBb3Ene0x5NCpmInK4=s900-c-k-c0x00ffffff-no-rj",
    "initials": "G",
    "description": "Dopo dieci anni di lavoro all'estero in qualità di Geologo, consulente scientifico e manager presso aziende nel mondo energetico, tra cui l'Istituto nazionale francese dell'energia, Andrea Moccia nel 2018 fonda Geopop. \"Il progetto è nato per scherzo, chiacchierando al bar con amici. Cominciai a fare video sulla geologia. Dopo 3 anni e 350 mila followers/iscritti l'impegno era talmente grande da diventare un secondo lavoro. Nel gennaio 2021, grazie a Ciaopeople, Geopop è diventata una startup, per cui ho lasciato il mio \"bel posto fisso\" per dedicarmici al 100%. Oggi la redazione è a Milano e il team cresce. Produciamo quasi un video al giorno su temi a cavallo tra le Scienze e la società moderna: geopolitica, energia, fenomeni naturali, terremoti e vulcani, ambiente, transizione ecologia, curiosità. Siamo schifosamente appassionati del nostro lavoro e vogliamo stimolare la curiosità e la fame di conoscenza delle persone\". Andrea Moccia",
