    "initials": "CB",
    "description": "Ciao a tutti! Sono Carlotta, insegnante di cucina, e incoraggio le persone a scegliere un'alimentazione vegetale, buona e sostenibile. Ho studiato e insegnato in una scuola di cucina, lavorando a Los Angeles, Barcellona e Milano. Oggi creo contenuti digitali sulle varie piattaforme di Cucina Botanica, e ho scritto anche un libro, che si intitola proprio \"Cucina Botanica\". Questo spazio è completamente dedicato a voi: troverete tante ricette gustose, consigli, idee per mangiare meglio - senza soffrire la mancanza di niente, ma anzi, godendovi ogni morso e imparando a consumare tanti nuovi ingredienti. Se non volete perdervi i prossimi video che pubblicherò, iscrivetevi al canale. Io sarò qui ogni settimana, se riesco anche di più. Carlotta NUOVI VIDEO OGNI SETTIMANA | ricette • alimentazione • sostenibilità BLOG | www.cucinabotanica.com EMAIL | info@cucinabotanica.com INSTAGRAM | @cucinabotanica",
