    "initials": "RR",
    "description": "🇷🇺 Russian podcasts🎤 and videos🎬 for RUSSIAN LEARNERS🤓 Hi everybody!! And welcome to the Russian Radio Show. My name is Sergey Griffits. I’m a host on a Russian radio station in Lithuania, a professional Russian language teacher both at a language school and online. Languages are my passion. I speak Russian, English, Italian and Lithuanian. The Russian Radio Show is a programme for those who study Russian. Here you can find interesting stories, interviews, explanations of grammar rules, useful advice and much more. So, you already speak Russian but would you like to do it better? Speak Russian fluently without pauses and making mistakes? Then the Russian Radio Show is for you! Subscribe, watch, listen, study Russian effortlessly! My website - https://russianradioshow.com/",
