    "initials": "RW",
    "description": "Со мной вы заговорите по-русски 😎 Welcome to Russian with Dasha – your ultimate channel for learning Russian through authentic and engaging content! Here, you’ll find: ⦿ Vlogs, dialogues, and interviews with native speakers in Russian, complete with Russian and English subtitles to boost your listening skills. ⦿ Behind-the-scenes insights into life in Saint Petersburg and fun everyday moments shared on my Telegram channel. For those looking to dive deeper, check out my Patreon channel! There, I: ⦿ Share video scripts with stressed words and English translations. ⦿ Provide podcast scripts to help you follow along and learn effectively. ⦿ Host live streams where we read stories in slow Russian and watch other useful materials together. I also host Russian with Dasha and co-host Russian Twist Podcast. Join my Conversational Club for lively debates in Russian (intermediate+ level). More info and booking for one-on-one lessons are available on my website. No 4981640719",
